                removed++;
            } else {
                currentEnd = Intervals[i][1];
            }
        }

        return removed;
    }
};
```

For example, after sorting `[[1,2],[2,3],[1,3],[3,4]]`, the interval `[1,3]` overlaps with the already kept `[2,3]`, so it is skipped. The result is `1`.

Time complexity: `O(n log n)`.
Space complexity: `O(1)` extra space, not counting the sorting implementation.

This is a simple exhaustive version. At each interval, the recursion tries both choices: remove it, or keep it when its start is allowed. A map stores states so the same index and previous end are not solved repeatedly.

It is useful for understanding the choices, but it is not the version to use for large input because the number of states can still grow quickly.

```javascript
class Solution {
    MaximumNonOverlappingIntervals(Intervals) {
        if (Intervals.length <= 1) {
            return 0;
        }

        Intervals.sort((a, b) => {
            if (a[0] !== b[0]) {
                return a[0] - b[0];
            }
            return a[1] - b[1];
        });

        const memo = new Map();

        const maximumKept = (index, previousEnd) => {
            if (index === Intervals.length) {
                return 0;
            }

            const key = index + ":" + previousEnd;
            if (memo.has(key)) {
                return memo.get(key);
            }

            const skip = maximumKept(index + 1, previousEnd);
            let keep = 0;

            if (Intervals[index][0] >= previousEnd) {
                keep = 1 + maximumKept(index + 1, Intervals[index][1]);
            }

            const answer = Math.max(skip, keep);
            memo.set(key, answer);
            return answer;
        };

        const kept = maximumKept(0, Number.NEGATIVE_INFINITY);
        return Intervals.length - kept;
    }
}
```

Dry run with `[[1,2],[1,3],[3,4]]`: the recursion can keep `[1,2]` and `[3,4]`, so the returned removal count is `1`. Intervals that touch at an endpoint are treated as non-overlapping.

The input array is sorted in place. This recursive form is mainly for small cases and learning, while a greedy or binary search DP solution is much safer for large cases.

Time complexity: `O(2^n)` in the worst case.
Space complexity: `O(2^n)` in the worst case for memoized states and recursion.

